      <TabsContent value="simulator"><div className="space-y-4"><div><p className="text-sm font-bold text-[#8a5e08]">Paso 3 de la materia</p><h3 className="mt-1 text-xl font-bold">Simulador de {currentSubject}</h3><p className="mt-2 text-sm text-slate-500">Integra preguntas aprobadas de los temas y formatos configurados de esta materia.</p></div>{subjectSimulatorCards.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{subjectSimulatorCards.map(r=><StudentCard key={r.id} row={r} onOpen={()=>setActive(r)}/>)}</div>:!featureAccess.simulator?<PermissionNotice/>:<Empty icon={FileQuestion} title="Simulador en preparación" text="Aparecerá cuando el profesor configure y publique el simulador de esta materia."/>}</div></TabsContent>
